function LadderStruggleAbstractPlayerTeam:MakeTeamData(teamInfo)
    local teamData = {}
    local team = teamInfo[1]

    local count = #team
    for i, cardInfo in ipairs(team) do
        local cardData = {
            cardId = cardInfo.cardId,
            advanceLevel = cardInfo.advanceLevel,
            star = cardInfo.star,
            cardLevel = cardInfo.level,
        }
        table.insert(teamData, cardData)
    end

    -- 不足4个队员的时候，补足4个
    if 4 - count > 0 then
        for i = 1, (4-count), 1 do
            table.insert(teamData, {})
        end
    end

    -- print("[快速战斗] 队员", table.dump(teamData, nil ,3))

    return teamData
end

